import{_ as a,o as e,c as r,ag as d}from"./chunks/framework.DGzMGr_a.js";const p=JSON.parse('{"title":"B站UP主深度测评：抢先体验RO3内测版本","description":"B站知名UP主带来RO3内测详细测评，涵盖职业体验、画面表现、GVG玩法、整体评价。","frontmatter":{"title":"B站UP主深度测评：抢先体验RO3内测版本","date":"2026-05-21T00:00:00.000Z","description":"B站知名UP主带来RO3内测详细测评，涵盖职业体验、画面表现、GVG玩法、整体评价。"},"headers":[],"relativePath":"news/beta-preview-202602.md","filePath":"news/beta-preview-202602.md","lastUpdated":1779362930000}'),l={name:"news/beta-preview-202602.md"};function o(i,t,h,n,s,b){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="b站up主深度测评-抢先体验ro3内测版本" tabindex="-1">B站UP主深度测评：抢先体验RO3内测版本 <a class="header-anchor" href="#b站up主深度测评-抢先体验ro3内测版本" aria-label="Permalink to &quot;B站UP主深度测评：抢先体验RO3内测版本&quot;">​</a></h1><p><strong>2026年5月21日</strong></p><p>RO3在2025年8月进行了首次Pioneer Test后，国内多位B站UP主获得了内测资格并分享了详细的游戏测评。以下是综合多位UP主的测评内容整理。</p><h2 id="画面与美术" tabindex="-1">画面与美术 <a class="header-anchor" href="#画面与美术" aria-label="Permalink to &quot;画面与美术&quot;">​</a></h2><h3 id="风格定位" tabindex="-1">风格定位 <a class="header-anchor" href="#风格定位" aria-label="Permalink to &quot;风格定位&quot;">​</a></h3><p>RO3的美术风格被多位UP主评价为「回归2D画风」的现代演绎。游戏采用「手绘描线+新复古渲染」技术，在保留RO经典像素质感的同时，实现了3D化的场景表现。</p><p><strong>亮点</strong>：</p><ul><li>普隆德拉主城完美3D重制，保留经典布局</li><li>角色建模细致，装备外观变化可见</li><li>动态天气系统（晴天、雨天、黄昏、夜晚）</li><li>技能特效华丽但不浮夸</li></ul><h3 id="争议点" tabindex="-1">争议点 <a class="header-anchor" href="#争议点" aria-label="Permalink to &quot;争议点&quot;">​</a></h3><p>部分UP主指出，相比当前市面上的MMO，RO3的画面并不算顶尖，但其独特的「RO味」美术风格是核心吸引力。</p><h2 id="职业系统" tabindex="-1">职业系统 <a class="header-anchor" href="#职业系统" aria-label="Permalink to &quot;职业系统&quot;">​</a></h2><h3 id="全职业三转试玩" tabindex="-1">全职业三转试玩 <a class="header-anchor" href="#全职业三转试玩" aria-label="Permalink to &quot;全职业三转试玩&quot;">​</a></h3><p>UP主「云千影Sorcer」在B站发布了全职业三转试玩视频，展示了：</p><ul><li><strong>骑士领主</strong>：骑乘战斗流畅，范围攻击表现优秀</li><li><strong>大法师</strong>：元素魔法华丽，AOE刷怪效率高</li><li><strong>十字刺客</strong>：双刀暴击流伤害可观</li><li><strong>大主教</strong>：实机展示了治疗和增益技能</li></ul><h3 id="职业平衡初步感受" tabindex="-1">职业平衡初步感受 <a class="header-anchor" href="#职业平衡初步感受" aria-label="Permalink to &quot;职业平衡初步感受&quot;">​</a></h3><table tabindex="0"><thead><tr><th>职业</th><th>测评评价</th><th>推荐度</th></tr></thead><tbody><tr><td>骑士</td><td>坦克定位明确，组队需求高</td><td>⭐⭐⭐⭐⭐</td></tr><tr><td>法师</td><td>AOE刷怪效率最高，单体爆发也不错</td><td>⭐⭐⭐⭐</td></tr><tr><td>刺客</td><td>后期成长性高，吃装备</td><td>⭐⭐⭐⭐</td></tr><tr><td>牧师</td><td>组队必备，F2P友好</td><td>⭐⭐⭐⭐⭐</td></tr><tr><td>弓箭手</td><td>远程安全输出，挂机首选</td><td>⭐⭐⭐⭐</td></tr><tr><td>商人</td><td>经济核心，战斗偏弱</td><td>⭐⭐⭐</td></tr></tbody></table><h2 id="gvg体验" tabindex="-1">GVG体验 <a class="header-anchor" href="#gvg体验" aria-label="Permalink to &quot;GVG体验&quot;">​</a></h2><p>UP主们对GVG的评价普遍较高：</p><ul><li>100v100的同屏人数表现流畅</li><li>攻城战的策略性比预期好</li><li>攻城武器（投石车、攻城锤）增加了战术维度</li><li>地形高低差影响战斗</li></ul><h2 id="系统评价" tabindex="-1">系统评价 <a class="header-anchor" href="#系统评价" aria-label="Permalink to &quot;系统评价&quot;">​</a></h2><h3 id="赛季制" tabindex="-1">赛季制 <a class="header-anchor" href="#赛季制" aria-label="Permalink to &quot;赛季制&quot;">​</a></h3><p>好评度较高，被认为能有效避免老玩家碾压新玩家的局面。</p><h3 id="自动战斗" tabindex="-1">自动战斗 <a class="header-anchor" href="#自动战斗" aria-label="Permalink to &quot;自动战斗&quot;">​</a></h3><p>70-80%手动效率，挂机友好但不失操作空间。</p><h3 id="交易系统" tabindex="-1">交易系统 <a class="header-anchor" href="#交易系统" aria-label="Permalink to &quot;交易系统&quot;">​</a></h3><p>保留了RO经典的摆摊系统，经济自由度高于当前主流MMO。</p><h2 id="整体评分" tabindex="-1">整体评分 <a class="header-anchor" href="#整体评分" aria-label="Permalink to &quot;整体评分&quot;">​</a></h2><p>综合多位UP主的评价，RO3内测版本评分约为：</p><table tabindex="0"><thead><tr><th>维度</th><th>评分</th><th>说明</th></tr></thead><tbody><tr><td>画面</td><td>7.5/10</td><td>风格独特但不顶尖</td></tr><tr><td>职业系统</td><td>8/10</td><td>传承经典，职业特色鲜明</td></tr><tr><td>GVG</td><td>9/10</td><td>核心亮点，大规模战斗体验出色</td></tr><tr><td>养成深度</td><td>8/10</td><td>技能搭配丰富</td></tr><tr><td>F2P友好度</td><td>8/10</td><td>赛季制+自由交易</td></tr><tr><td>综合</td><td><strong>8/10</strong></td><td>值得期待的RO正统续作</td></tr></tbody></table><blockquote><p><strong>总结</strong>：RO3内测版本展现了不错的素质，特别是在GVG和职业系统方面得到了玩家社群的一致好评。虽然画面不是最顶尖的，但独特的RO风格和扎实的玩法设计，让这款正统续作值得所有RO粉丝期待。</p></blockquote>',30)])])}const u=a(l,[["render",o]]);export{p as __pageData,u as default};
